var charvoice_list = {"char_010_chen":{"cn_001":"博士，现在起由我担任你的护卫。","cn_002":"我一直觉得你们罗德岛很可疑，现在也一样。","cn_003":"你怎么还在盯着我看？你的工作呢？","cn_004":"哼。","cn_005":"龙门的大街小巷我都走过。码头、招牌、坡道，那些风景印在我的心上。我永远都不会忘记。","cn_006":"周边地区的局势并不稳定，虽然我会时刻保持警戒，但你也不能疏忽大意。","cn_007":"也许有一天我会得到那个人的认可，在那之前......","cn_008":"阿米娅深深信赖着你。看着你们两人站在一起，我偶尔也会觉得，如果我身边，也能有这样一个人......","cn_009":"我......我从没试过去毫无保留地相信一个人，即使是那个人也......","cn_010":"博士？睡着了？哼，真没紧张感。","cn_011":"陈，龙门近卫局特别督察组组长。基于一些特殊原因，我要暂时留在这里一段时间。之前的合作中，我想我们已经彼此了解了，请马上带我去工作现场吧。","cn_034":"喂！干什么呢！","cn_036":"博士，你心情不错嘛，因为最近作战比较顺利？正巧，我也一样。","cn_037":"明日方舟。","cn_042":"哦，是博士啊。"},"char_010_chen_cn_TOPOLECT":{"cn_001":"博士，接下来就由我担任你的护卫。","cn_002":"我一向都觉得你们罗德岛很可疑，现在这一刻也是这么觉得。","cn_003":"你怎么还在看着我？你手头要做的的东西呢？","cn_004":"哼。","cn_005":"龙门的每一条街道每一条巷子我都行过。码头、招牌、斜坡，那些风景已经全部进了我的心。我永远都会记得。","cn_006":"周边地区的局势唔系好稳定，我会时刻保持警戒，不过你也唔好疏忽大意。","cn_007":"或许有一天我会得到那个人的认可，在那天来到之前......","cn_008":"阿米娅真的很信任你。就这么看着你们两人站在一齐，我有时候会觉得，如果在我身边，同样有一个这样的人......","cn_009":"我......我之前没试过毫无保留地相信一个人，就算是那个人也......","cn_010":"博士？睡着了？哼，一点紧张感也冇。","cn_011":"陈，龙门近卫局特别督察组组长。基于一些特殊原因，我要暂时留在这里一段时间。经过之前的合作，我相信我们已经充分了解对方，麻烦即刻带我去工作现场吖。","cn_034":"喂！做咩啊！","cn_036":"博士，你心情不错嘛，是因为最近的行动都比较顺利？真系巧，我也一样。","cn_037":"明日方舟。","cn_042":"哦，系博士呀。"}};
